window.SOLAR_COURSES=[
{name:'太陽發電島',desc:'從陽光到電能，設計一場公平的太陽能探究。',icon:'☀',color:'#74b581',tint:'#e9f3e6',tag:'太陽能延伸 × 提問',tasks:['辨認：說明陽光轉換成電能的過程','預測：光照或角度改變會怎樣？','設計：一次只改變一項條件'],x:-170,z:-80},
{name:'儲能解密島',desc:'看懂 mAh、Wh 與額定容量，先留下自己的預測。',icon:'▥',color:'#d7a95b',tint:'#fbf1dc',tag:'教案活動 × 標示解讀',tasks:['讀標示：記錄容量、電壓與輸出規格','先手算：把 mAh 換成 Wh','先預測：寫下風扇能運轉多久與理由'],x:165,z:-115},
{name:'風扇量測島',desc:'串接 USB 電力計，每分鐘記錄一次，取得自己的證據。',icon:'✣',color:'#b69bc6',tint:'#f1eaf7',tag:'AI 紅燈 × 親手量測',tasks:['準備：分工、檢查接線、電力計歸零','量測：完成 0～10 分鐘共 11 筆紀錄','手算：平均功率、耗能與推估時間'],x:-155,z:155},
{name:'能源驗證島',desc:'先有自己的推理，再查證 AI，提出有依據的能源方案。',icon:'◇',color:'#74abbc',tint:'#e5f1f6',tag:'AI 查證 × 發表反思',tasks:['查證：對照手算與 AI，指出採用或修正之處','發表：呈現量測數據並揭露 AI 使用方式','反思：比較教師完整放電數據，說明誤差'],x:175,z:145}
];
window.enrichSolarLesson=function(i,body){
const add=(t,c)=>{const p=document.createElement(t);p.textContent=c;body.append(p);return p};
const notes=[
['太陽能延伸活動｜約 10 分鐘，可另排一節','本島為依課程主題新增的延伸活動；原教案的主體是行動電源耗電實測。','能量路徑：陽光 → 太陽能板 → 相容的充電控制／儲能設備 → USB 電力計 → 風扇。太陽能板不可任意直接接行動電源，請由教師確認設備輸入規格與保護功能。','先預測，再比較：保持同一片板、同一負載與量測方式，只改變光照條件或板面角度。記錄 V、A、W 與環境；戶外變動的日照會影響公平比較。','思考：太陽能板的標示功率是否等於每次都能輸出的功率？陰影、角度與天氣可能造成什麼影響？'],
['教案第 1、2 段｜5＋5 分鐘','紅燈：先自行讀標示、抄錄規格與提出預測。黃燈：再問 AI「mAh 與 Wh 有何不同？」保留完整對話與工具名稱。','電能 Wh＝容量 mAh × 該容量所對應的電壓 V ÷ 1000。內部電池容量常以約 3.7 V 標示，仍應以本機標示為準；USB 額定容量則可能對應 5 V。電壓不同的 mAh 不能直接比較。','教案例子：5000 mAh × 3.7 V ÷ 1000＝18.5 Wh。先寫下你認為風扇能運轉多久，並說明理由。'],
['教案第 3 段｜15 分鐘，其中連續量測 10 分鐘','紅燈：量測、核心手算與現場寫作均不使用 AI。3～4 人分工為操作員、計時紀錄員、數據管理員及安全觀察員，可兼任。','接線：行動電源 → USB 電力計 → 有護網的 USB 風扇。歸零後設定固定檔位；第 0 分鐘為起始值，第 1～10 分鐘各一筆，共 11 筆。','第 5、10 分鐘留意溫度；第 10 分鐘拍攝電力計畫面。行動電源鼓脹、明顯發熱或有異味應停止使用並通知教師。手指、頭髮、線材遠離葉片。市電與充電器比較由教師確認及操作。','先手算：第 1～10 分鐘功率相加 ÷ 10＝平均功率 W。10 分鐘耗能為累積 Wh 的終值減起始值；歸零成功時可直接讀終值。以平均功率 × 10 ÷ 60 交叉核對。','短時耗能占比不等於轉換效率。10 分鐘沒有放完整顆電池，不能把這段輸出 Wh ÷ 標示 Wh 當作完整放電效率。'],
['教案第 4、5 段｜10＋15 分鐘','黃燈：先量完、先手算，再提供本組數據給 AI 核對。綠燈：可用 AI 協助海報排版及文字潤飾；口試時不使用 AI。','推估可運轉時間 h＝標示電能 Wh × 假設效率 ÷ 平均功率 W。效率是本組提出的假設，並非 10 分鐘實測得出的完整轉換效率。','教案示例：18.5 Wh × 75% ÷ 4 W ≈ 3.47 小時。將推估與教師預先完成的完整放電實測相比，討論發熱、電量降低與轉速變動。','口試：為何不同電壓的 mAh 不能直接比？效率為何這樣假設？改高檔後時間如何變？哪一項 AI 建議被修正？短時推估有何限制？','繳交：完整 AI 對話連結或含時間的全程截圖、工具與日期、採用／修正／拒絕內容、對應手算或原始數據；避免輸入姓名與個人照片。','依教案評量：量測 15%、現場寫作 20%、口試 20%、推估與 AI 查證 20%、圖卡與 AI 揭露 15%、互動 10%。原稿另有「一半」文字敘述，本頁以明列權重呈現。']
];
const section=add('section','');section.className='lesson-content';notes[i].forEach((s,j)=>{const p=document.createElement(j===0?'h3':'p');p.textContent=s;section.append(p)});
if(i===0){const p=document.createElement('p');p.className='energy-flow';p.textContent='☀ 陽光　→　▱ 發電　→　▥ 儲能　→　✣ 用電';section.append(p)}
if(i===2)measurement(section);
if(i===3)calculator(section);
const label=document.createElement('label');label.className='reflection-label';label.textContent=i===3?'我的查證、AI 使用揭露與反思':'我的預測、觀察與理由';const text=document.createElement('textarea');text.rows=4;text.placeholder='用自己的話寫下想法；可隨紀錄一起匯出。';text.setAttribute('aria-label',label.textContent);let state=readLab();text.value=state['note'+i]||'';text.oninput=()=>{const s=readLab();s['note'+i]=text.value;writeLab(s)};label.append(text);body.append(label);const exportButton=document.createElement('button');exportButton.className='small';exportButton.textContent='下載本機學習紀錄';exportButton.onclick=()=>downloadLab();body.append(exportButton);add('p','參考：使用者提供之「第二單元設計：量與測—以電力計與暴力風扇量測耗電」。太陽能島為新增延伸；本頁紀錄僅存於此瀏覽器，下載檔案後請另交教師。');
};
function readLab(){try{return JSON.parse(localStorage.getItem('solar-lab-v1')||'{}')}catch{return {}}}function writeLab(s){try{localStorage.setItem('solar-lab-v1',JSON.stringify(s))}catch{alert('瀏覽器無法儲存，請允許本機儲存後再填寫。')}}
function measurement(root){const h=document.createElement('h3');h.textContent='我的 10 分鐘實測表';root.append(h);const scroll=document.createElement('div');scroll.className='lab-scroll';const table=document.createElement('table');const head=document.createElement('thead');const tr=document.createElement('tr');['分鐘','V','A','W','mAh','Wh','觀察'].forEach(t=>{const th=document.createElement('th');th.textContent=t;th.scope='col';tr.append(th)});head.append(tr);table.append(head);const tbody=document.createElement('tbody'),s=readLab();for(let m=0;m<=10;m++){const row=document.createElement('tr'),th=document.createElement('th');th.textContent=m;th.scope='row';row.append(th);['v','a','w','mah','wh','obs'].forEach(k=>{const cell=document.createElement('td'),input=document.createElement('input');input.setAttribute('aria-label','第 '+m+' 分鐘 '+k);input.type=k==='obs'?'text':'number';if(k!=='obs'){input.step='any';input.min='0'}input.value=(s.rows||{})[m+'-'+k]||'';input.oninput=()=>{const s=readLab();s.rows=s.rows||{};s.rows[m+'-'+k]=input.value;writeLab(s)};cell.append(input);row.append(cell)});tbody.append(row)}table.append(tbody);scroll.append(table);root.append(scroll);const p=document.createElement('p');p.textContent='紅燈階段先自行完成手算，本表不自動產生答案。第 5 與第 10 分鐘請記錄溫度觀察。';root.append(p)}
function calculator(root){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='已完成手算，開啟推估核對工具';details.append(summary);const form=document.createElement('form');form.className='calc-form';const fields=[['capacity','標示容量（mAh）','5000'],['voltage','容量對應電壓（V）','3.7'],['efficiency','假設效率（%）','75'],['power','平均功率（W）','4']];fields.forEach(([key,title,placeholder])=>{const label=document.createElement('label');label.textContent=title;const input=document.createElement('input');input.type='number';input.name=key;input.min=key==='efficiency'?'0':'0.00001';if(key==='efficiency')input.max=100;input.step='any';input.required=true;input.placeholder=placeholder;label.append(input);form.append(label)});const b=document.createElement('button');b.className='primary';b.textContent='核對推估';form.append(b);const out=document.createElement('output');out.setAttribute('aria-live','polite');form.append(out);form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),c=+f.get('capacity'),v=+f.get('voltage'),eta=+f.get('efficiency')/100,p=+f.get('power');if(!(c>0&&v>0&&p>0&&eta>=0&&eta<=1))return;const wh=c*v/1000,h=wh*eta/p;out.textContent='標示電能 '+wh.toFixed(2)+' Wh；假設可用電能 '+(wh*eta).toFixed(2)+' Wh；推估 '+h.toFixed(2)+' 小時。此為固定平均功率與假設效率下的估計。'};details.append(form);root.append(details)}
function downloadLab(){const content={課程:'太陽能教學島',匯出時間:new Date().toISOString(),量測與反思:readLab()};try{content.任務進度=JSON.parse(localStorage.getItem('solar-island-template-v1')||'{}')}catch{}const blob=new Blob([JSON.stringify(content,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='太陽能教學島_學習紀錄.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
